class AutomatedTellerMachineSystem_AutoGenerated {
  /*SystemVariable Start*/
  PasswordValidated: boolean;
  WithdrawedNumber: number;
  InputCard: BankCard;
  CardIDValidated: boolean;
  IsDeposit: boolean;
  IsWithdraw: boolean;
  DepositedNumber: number;
  /*SystemVariable End*/

  /*the card id and password is validated and the input card exist, then if the money is withdraw,
   *if print the withdrawed number or if it is deposit print the deposited number or print 0*/
  printReceipt(): number {
    /*Definition Start*/
    let inputCard: BankCard = l({
      logic: () =>
        getRepository(BankCard).find(
          (o: any) =>
            l({
              logic: () => o.CardID === this.CardIDValidated,
              description: "o.CardID=self.CardIDValidated",
            })
              .and({
                logic: () => o.Password === this.PasswordValidated,
                description: "o.Password=self.PasswordValidated",
              })
              .build().pass,
        ),
      description:
        "BankCard.allInstance()->any(o|o.CardID=self.CardIDValidatedando.Password=self.PasswordValidated)",
    }).build().pass;
    let isWithdraw: boolean = l()
      .if({
        logic: () =>
          l({
            logic: () => this.IsDeposit,
            description: "self.IsDeposit",
          }),
        description: "self.IsDeposit",
        then: l({
          logic: () => false,
          description: "false",
        }),
        else: l({
          logic: () => true,
          description: "true",
        }),
      })
      .build().pass;
    let withdrawedNumber: number = l()
      .if({
        logic: () =>
          l({
            logic: () => isWithdraw,
            description: "isWithdraw",
          }),
        description: "isWithdraw",
        then: l({
          logic: () => this.DepositedNumber,
          description: "self.DepositedNumber",
        }),
        else: l({
          logic: () => 0,
          description: "0",
        }),
      })
      .build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsTypeOf(this.CardIDValidated, Integer),
        description: "self.CardIDValidated.oclIsTypeOf(Integer)",
      })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(this.PasswordValidated, Integer),
          description: "self.PasswordValidated.oclIsTypeOf(Integer)",
        })
        .and({
          logic: () => StandardOPs.oclIsUndefined(inputCard) === false,
          description: "inputCard.oclIsUndefined()=false",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    return l({
      execute: () =>
        (inputCard.Balance = inputCard.Balance - this.DepositedNumber),
      description: "inputCard.Balance=inputCard.Balance-self.DepositedNumber",
    })
      .and({
        execute: () => withdrawedNumber,
        description: "result=withdrawedNumber",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { AutomatedTellerMachineSystem_AutoGenerated };

